const mix=(a,b,weight)=>{const av=a.slice(1).match(/../g).map(v=>parseInt(v,16)),bv=b.slice(1).match(/../g).map(v=>parseInt(v,16));return '#'+av.map((v,i)=>Math.round(v*(1-weight)+bv[i]*weight).toString(16).padStart(2,'0')).join('');};
const luminance=hex=>hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0);
const contrast=(a,b)=>{const x=luminance(a),y=luminance(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05);};
function palette(color){
  // User color changes only the page backdrop, brand and small focus accents.
  const values={accent:color,'on-accent':contrast(color,'#ffffff')>=contrast(color,'#000000')?'#ffffff':'#000000',paper:mix('#f6f8fc',color,.06),surface:'#ffffff',tint:'#f5f8fc',selected:'#eaf2fa',line:'#dce4ed',ink:'#28364a',muted:'#596b7f'};
  let emphasis=color;for(let i=0;i<25&&Math.min(...['paper','surface','tint','selected'].map(bg=>contrast(emphasis,values[bg])))<4.5;i++)emphasis=mix(emphasis,'#20314b',.12);values['accent-text']=emphasis;
  return values;
}
